18: along with this program. If not, see http://www.gnu.org/licenses/ .
19: */
20: 
21: #ifndef __MPC_H
22: #define __MPC_H
23: 
24: #include <stdint.h>
25: #include "gmp.h"
26: #include "mpfr.h"
27: 
28: #if @MPC_HAVE_COMPLEX_H@
29: #define _MPC_HAVE_COMPLEX_H
30: #else
31: #undef _MPC_HAVE_COMPLEX_H
32: #endif
33: 
34: /* Define MPC version number */
35: #define MPC_VERSION_MAJOR 1
36: #define MPC_VERSION_MINOR 4
37: #define MPC_VERSION_PATCHLEVEL 2
38: #define MPC_VERSION_STRING "1.4.2dev"
39: 
40: /* Macros dealing with MPC VERSION */
41: #define MPC_VERSION_NUM(a,b,c) (((a) << 16L) | ((b) << 8) | (c))
42: #define MPC_VERSION                                                     \
43:   MPC_VERSION_NUM(MPC_VERSION_MAJOR,MPC_VERSION_MINOR,MPC_VERSION_PATCHLEVEL)
44: 
45: /* Check if stdint.h/inttypes.h is included */
46: #if defined (INTMAX_C) && defined (UINTMAX_C)
47: #define _MPC_H_HAVE_INTMAX_T 1
48: #endif
49: 
50: /* Return values */
51: 
52: /* Transform negative to 2, positive to 1, leave 0 unchanged.
53:    Warning: since inex is evaluated two times, we should avoid
54:    MPC_INEX(mpc_mul (...), mpc_mul (...)) */
55: #define MPC_INEX_POS(inex) (((inex) < 0) ? 2 : ((inex) == 0) ? 0 : 1)
56: /* Transform 2 to negative, 1 to positive, leave 0 unchanged */
57: #define MPC_INEX_NEG(inex) (((inex) == 2) ? -1 : ((inex) == 0) ? 0 : 1)
58: 
59: /* The global inexact flag is made of (real flag) + 4 * (imaginary flag), where
60:    each of the real and imaginary inexact flag are:
61:    0 when the result is exact (no rounding error)
62:    1 when the result is larger than the exact value
63:    2 when the result is smaller than the exact value */
64: #define MPC_INEX(inex_re, inex_im) \
65:         (MPC_INEX_POS(inex_re) | (MPC_INEX_POS(inex_im) << 2))
66: #define MPC_INEX_RE(inex) MPC_INEX_NEG((inex) & 3)
67: #define MPC_INEX_IM(inex) MPC_INEX_NEG((inex) >> 2)
68: 
69: /* For functions computing two results, the return value is
70:    inexact1+16*inexact2, which is 0 iif both results are exact. */
71: #define MPC_INEX12(inex1, inex2) (inex1 | (inex2 << 4))
72: #define MPC_INEX1(inex) (inex & 15)
73: #define MPC_INEX2(inex) (inex >> 4)
74: 
75: /* Definition of rounding modes */
76: 
77: /* a complex rounding mode is just a pair of two real rounding modes
78:    we reserve four bits for a real rounding mode.  */
79: typedef int mpc_rnd_t;
80: 
81: #define MPC_RND(r1,r2) (((int)(r1)) + ((int)(r2) << 4))
82: #define MPC_RND_RE(x) ((mpfr_rnd_t)((x) & 0x0F))
83: #define MPC_RND_IM(x) ((mpfr_rnd_t)((x) >> 4))
84: 
85: #define MPC_RNDNN MPC_RND (MPFR_RNDN,MPFR_RNDN)
86: #define MPC_RNDNZ MPC_RND (MPFR_RNDN,MPFR_RNDZ)
87: #define MPC_RNDNU MPC_RND (MPFR_RNDN,MPFR_RNDU)
88: #define MPC_RNDND MPC_RND (MPFR_RNDN,MPFR_RNDD)
89: #define MPC_RNDNA MPC_RND (MPFR_RNDN,MPFR_RNDA)
90: 
91: #define MPC_RNDZN MPC_RND (MPFR_RNDZ,MPFR_RNDN)
92: #define MPC_RNDZZ MPC_RND (MPFR_RNDZ,MPFR_RNDZ)
93: #define MPC_RNDZU MPC_RND (MPFR_RNDZ,MPFR_RNDU)
94: #define MPC_RNDZD MPC_RND (MPFR_RNDZ,MPFR_RNDD)
